1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Scenario {
6	  customer: Customer;
7	  steps: Step[];
8	}
9	
10	export interface QuoteStep {
11	  op: "quote";
12	  items: Item[];
13	}
14	
15	export interface Item {
16	  type: string;
17	  material?: string;
18	  enchantment?: number;
19	  cursed?: boolean;
20	}
21	
22	export interface Damage {
23	  itemType: string;
24	  amount: number;
25	}
26	
27	export interface Incident {
28	  cause: string;
29	  damages: Damage[];
30	}
31	
32	export interface ClaimStep {
33	  op: "claim";
34	  policy: number;
35	  incident: Incident;
36	}
37	
38	export type Step = QuoteStep | ClaimStep;
39	
40	export interface QuoteResult {
41	  premium: number;
42	}
43	
44	export interface ClaimResult {
45	  payout: number;
46	  remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioResult {
52	  results: StepResult[];
53	}
54	
55	const sumBy = <T>(values: T[], amountOf: (value: T) => number): number =>
56	  values.reduce((total, value) => total + amountOf(value), 0);
57	
58	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
59	  sword: 100,
60	  amulet: 60,
61	  staff: 80,
62	  potion: 40,
63	  rune: 25,
64	  moonstone: 25,
65	};
66	
67	const itemBasePremium = (item: Item): number => {
68	  const basePremium = BASE_PREMIUM_BY_TYPE[item.type];
69	  if (basePremium === undefined) {
70	    throw new Error(`The MHPCO does not insure items of type "${item.type}"`);
71	  }
72	  return basePremium;
73	};
74	
75	const BLOCK_SIZE = 3;
76	
77	const BLOCK_BASE_PREMIUM = 60;
78	
79	const basePremiumForSameTypeItems = (items: Item[]): number =>
80	  items.length === BLOCK_SIZE
81	    ? BLOCK_BASE_PREMIUM
82	    : sumBy(items, itemBasePremium);
83	
84	const sameTypeGroups = (items: Item[]): Item[][] => {
85	  const groupsByType = new Map<string, Item[]>();
86	  for (const item of items) {
87	    const group = groupsByType.get(item.type) ?? [];
88	    group.push(item);
89	    groupsByType.set(item.type, group);
90	  }
91	  return [...groupsByType.values()];
92	};
93	
94	const CURSE_SURCHARGE_RATE = 0.5;
95	
96	const HIGH_ENCHANTMENT_LEVEL = 5;
97	
98	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
99	
100	interface SurchargeRule {
101	  appliesTo: (item: Item) => boolean;
102	  rate: number;
103	}
104	
105	const SURCHARGE_RULES: SurchargeRule[] = [
106	  {
107	    appliesTo: (item) => item.cursed === true,
108	    rate: CURSE_SURCHARGE_RATE,
109	  },
110	  {
111	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL,
112	    rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
113	  },
114	];
115	
116	const itemSurchargeRate = (item: Item): number =>
117	  sumBy(
118	    SURCHARGE_RULES.filter((rule) => rule.appliesTo(item)),
119	    (rule) => rule.rate,
120	  );
121	
122	const itemSurcharge = (item: Item): number =>
123	  itemBasePremium(item) * itemSurchargeRate(item);
124	
125	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
126	
127	const PROCESSING_FEE = 5;
128	
129	const LOYALTY_YEARS = 2;
130	
131	const LOYALTY_DISCOUNT_RATE = 0.2;
132	
133	const loyaltyDiscountRate = (customer: Customer): number =>
134	  customer.yearsWithMHPCO >= LOYALTY_YEARS ? -LOYALTY_DISCOUNT_RATE : 0;
135	
136	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
137	
138	const followUpContractDiscountRate = (precedingContracts: number): number =>
139	  precedingContracts > 0 ? -FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0;
140	
141	// Policy-wide modifiers are rates applied to the policy base premium.
142	// Surcharges are positive rates, discounts negative ones.
143	const policyModifierRate = (
144	  customer: Customer,
145	  precedingContracts: number,
146	): number =>
147	  FIRST_INSURANCE_SURCHARGE_RATE +
148	  loyaltyDiscountRate(customer) +
149	  followUpContractDiscountRate(precedingContracts);
150	
151	const quotePremium = (
152	  step: QuoteStep,
153	  customer: Customer,
154	  precedingContracts: number,
155	): number => {
156	  const policyBasePremium = sumBy(
157	    sameTypeGroups(step.items),
158	    basePremiumForSameTypeItems,
159	  );
160	  const itemSurcharges = sumBy(step.items, itemSurcharge);
161	  // Keep this as `base + base * rate`. Factoring it to `base * (1 + rate)`
162	  // introduces IEEE-754 drift that is always upward (e.g. base 180 at rate 0.1
163	  // gives 198.00000000000003 instead of 198), and Math.ceil below turns any
164	  // such drift into a full extra G. Sword + staff would quote 204, not 203.
165	  const policyModifierAmount =
166	    policyBasePremium * policyModifierRate(customer, precedingContracts);
167	  // Rounded in the MHPCO's favour; only the final premium is rounded.
168	  return Math.ceil(
169	    policyBasePremium + itemSurcharges + policyModifierAmount + PROCESSING_FEE,
170	  );
171	};
172	
173	// Deliberately kept separate from BASE_PREMIUM_BY_TYPE. The two tables share a
174	// key domain but not a fact: an item's base premium and its insurance value are
175	// independent numbers the spec states separately. Merging them into one
176	// catalogue would couple them in the reader's mind for no gain.
177	const INSURANCE_VALUE_BY_TYPE: Record<string, number> = {
178	  sword: 1000,
179	  amulet: 600,
180	  staff: 800,
181	  potion: 400,
182	  rune: 250,
183	  moonstone: 250,
184	};
185	
186	const insuranceValue = (item: Item): number =>
187	  INSURANCE_VALUE_BY_TYPE[item.type];
188	
189	// The block discount affects the premium only, never the insurance sum.
190	const insuranceSum = (policy: QuoteStep): number =>
191	  sumBy(policy.items, insuranceValue);
192	
193	const DEDUCTIBLE = 100;
194	
195	const CAP_MULTIPLE = 2;
196	
197	const REDUCED_REIMBURSEMENT_ENCHANTMENT = 8;
198	
199	const REDUCED_REIMBURSEMENT_RATE = 0.5;
200	
201	const FULL_REIMBURSEMENT_RATE = 1;
202	
203	// Named for the trigger (enchantment level), to keep it distinct from the
204	// premium-side HIGH_ENCHANTMENT_LEVEL, which is a different threshold (5).
205	const reimbursementRate = (item: Item): number =>
206	  (item.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_ENCHANTMENT
207	    ? REDUCED_REIMBURSEMENT_RATE
208	    : FULL_REIMBURSEMENT_RATE;
209	
210	// The deductible is withheld once per damage entry, not once per incident,
211	// and applies after any reimbursement clause has reduced the amount.
212	// Clamped per entry, not on the total: a damage smaller than the deductible
213	// yields nothing, but must not eat into another damage's reimbursement.
214	const payableForDamage = (damage: Damage, item: Item): number => {
215	  const reimbursement = damage.amount * reimbursementRate(item);
216	  return Math.max(0, reimbursement - DEDUCTIBLE);
217	};
218	
219	// Which insured item a damage entry refers to. Matching on type alone is
220	// enough while every test damages a type the policy covers; the pending
221	// "item not part of the policy" and "more damage entries than covered" cases
222	// will need this to reject rather than return a match, which is why the
223	// lookup is named and separate rather than inlined behind a cast.
224	const insuredItemFor = (damage: Damage, policy: QuoteStep): Item =>
225	  policy.items.find((item) => item.type === damage.itemType) as Item;
226	
227	const policyCap = (policy: QuoteStep): number =>
228	  insuranceSum(policy) * CAP_MULTIPLE;
229	
230	// The cap is a per-policy budget: a claim pays out at most what is left of it.
231	const settleClaim = (
232	  step: ClaimStep,
233	  policy: QuoteStep,
234	  capRemaining: number,
235	): ClaimResult => {
236	  const payable = sumBy(step.incident.damages, (damage) =>
237	    payableForDamage(damage, insuredItemFor(damage, policy)),
238	  );
239	  // Rounded in the MHPCO's favour — down, the opposite of the premium's
240	  // Math.ceil. Only the final payout is rounded, and the cap is decremented by
241	  // the rounded figure so the remaining cap stays in whole G.
242	  const payout = Math.floor(Math.min(payable, capRemaining));
243	  return { payout, remainingCap: capRemaining - payout };
244	};
245	
246	export const runScenario = (scenario: Scenario): ScenarioResult => {
247	  const results: StepResult[] = [];
248	  const capRemainingByPolicy = new Map<number, number>();
249	  // Only quote steps conclude a contract, so this cannot be derived from the
250	  // step index: a claim step must not earn the next quote its follow-up
251	  // discount. Incremented after pricing, so during a quote it holds the number
252	  // of contracts concluded *before* that quote — hence `preceding`.
253	  let precedingContracts = 0;
254	  for (const step of scenario.steps) {
255	    if (step.op === "quote") {
256	      results.push({
257	        premium: quotePremium(step, scenario.customer, precedingContracts),
258	      });
259	      precedingContracts += 1;
260	    } else {
261	      const policy = scenario.steps[step.policy] as QuoteStep;
262	      const capRemaining =
263	        capRemainingByPolicy.get(step.policy) ?? policyCap(policy);
264	      const result = settleClaim(step, policy, capRemaining);
265	      capRemainingByPolicy.set(step.policy, result.remainingCap);
266	      results.push(result);
267	    }
268	  }
269	  return { results };
270	};
