// Named for symmetry with itemBasePremium: both are per-item lookups, and the
// pairing is what makes the next line's asymmetry visible.
// NOTE: unlike itemBasePremium, this does NOT reject an unknown type — it
// returns undefined and poisons the insurance sum with NaN. No test reaches it
// (a quote with an unknown type throws before any claim can be settled), so the
// gap is recorded rather than closed; the pending "claim referencing an item
// with an unknown type" case is where it should be fixed.
const itemInsuranceValue = (item: Item): number =>
  INSURANCE_VALUE_BY_TYPE[item.type];

// The block discount affects the premium only, never the insurance sum.
const insuranceSum = (policy: QuoteStep): number =>
  sumBy(policy.items, itemInsuranceValue);

// NOTE: the block branch is the one path that never consults itemBasePremium,
// so it is also the one path that never rejects an unknown type — exactly three
// broomsticks would quote 60 G instead of throwing. No test covers it; left as
// is rather than implementing ahead of one.
const basePremiumForSameTypeItems = (items: Item[]): number =>
  items.length === BLOCK_SIZE
    ? BLOCK_BASE_PREMIUM
    : sumBy(items, itemBasePremium);
